import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createServer} from 'node:http';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import ts from 'typescript';
import sharp from 'sharp';
import {chromium} from '@playwright/test';
const review='.local/step07-review/independent-round11';
const original=await readFile('apps/api/tests/studio/received-resources.ts','utf8');
await writeFile(review+'/private/received-exact.mjs',ts.transpileModule(original,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext}}).outputText);
const {ReceivedResources}=await import('./received-exact.mjs');
const a=await readFile('tests/fixtures/art-water-0.png'),b=await readFile('tests/fixtures/art-water-1.png');
const hash=x=>createHash('sha256').update(x).digest('hex'),urlpath='/api/projects/owned/recipes/revisionA/processed?frame=0';
const html=`<script>window.load=async function(path,render=true){const c=new AbortController;window.last=c;const r=await fetch(path,{signal:c.signal,cache:'no-store'});const body=await r.arrayBuffer();const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',body)),x=>x.toString(16).padStart(2,'0')).join('');if(render){const i=new Image;i.src=URL.createObjectURL(new Blob([body],{type:'image/png'}));await i.decode();i.id='actual';i.dataset.sha=sha;document.getElementById('actual')?.remove();document.body.append(i)}return sha};</script>`;
const plans=[]; const holds=[]; const events=[];
function plan(body,hold=false){let enter;const arrived=new Promise(r=>enter=r);const obj={body,hold,arrived,enter};plans.push(obj);return obj}
const server=createServer((req,res)=>{if(!req.url.startsWith('/api/'))return res.end(html);const p=plans.shift();assert(p);p.response=res;events.push({url:req.url,receivedHeaders:true});res.writeHead(200,{'content-type':'image/png','cache-control':'no-store'});if(p.hold){holds.push(res);res.flushHeaders();res.write(p.body.subarray(0,8));p.enter()}else{res.end(p.body);p.enter()}});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;
const browser=await chromium.launch();const page=await browser.newPage();const capture=new ReceivedResources(page,origin,'owned');const old=new Map();let navigations=0;const errors=[];
page.on('framenavigated',f=>{if(f===page.mainFrame())navigations++});page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.url()===origin+urlpath){const v=r.body();void v.catch(()=>{});old.set(r.url(),v)}});
async function wait(fn){const end=Date.now()+5000;while(!fn()){assert(Date.now()<end,'independent 5s capture deadline');await new Promise(r=>setTimeout(r,10))}}
async function complete(body,path=urlpath,render=true){const p=plan(body);await page.evaluate(({path,render})=>window.load(path,render),{path,render});await p.arrived;await wait(()=>capture.find(origin+path,hash(body)))}
async function pixels(){const h=await page.locator('#actual').getAttribute('data-sha');const e=capture.find(origin+urlpath,h);assert(e,'current completed actual body required');const actual=await page.locator('#actual').evaluate(i=>{const c=document.createElement('canvas');c.width=i.naturalWidth;c.height=i.naturalHeight;const x=c.getContext('2d');x.drawImage(i,0,0);return {size:[c.width,c.height],rgba:Array.from(x.getImageData(0,0,c.width,c.height).data)}});const decoded=await sharp(e.bytes).ensureAlpha().raw().toBuffer({resolveWithObject:true});assert.deepEqual(actual.size,[96,144]);assert.deepEqual(Buffer.from(actual.rgba),decoded.data);return {id:e.id,sha:e.sha,rgbaSha:hash(decoded.data),url:e.url,document:e.document}}
const outcomes=[];
try{
 await page.goto(origin);await complete(a);const initial=await pixels();
 const held=plan(b,true),reply=page.waitForResponse(origin+urlpath),failed=page.waitForEvent('requestfailed');await page.evaluate(path=>{window.pending=window.load(path).catch(e=>e.name)},urlpath);await reply;await held.arrived;
 assert.equal(capture.find(origin+urlpath,hash(b)),undefined);outcomes.push({case:'current unfinished body refuses match',pass:true});
 await page.evaluate(()=>window.last.abort());await failed;let oldError;try{await old.get(origin+urlpath);assert.fail('old URL map must reject')}catch(e){oldError=e.message;assert.match(oldError,/Network.getResponseBody.*No data found for resource/)}await wait(()=>capture.snapshot().some(x=>x.state==='unavailable'));const retained=await pixels();assert.equal(retained.id,initial.id);assert.equal(navigations,1);outcomes.push({case:'real 200 partial cancel old map rejects; same actual DOM body preserved',pass:true,oldError,navigations,initial,retained});
 await complete(b);const replacement=await pixels();assert.notEqual(replacement.id,initial.id);outcomes.push({case:'new completed actual body replaces old displayed SHA and RGBA',pass:true,replacement});
 const iframeEntered=plan(a),frameResponse=page.waitForResponse(origin+urlpath);await page.evaluate(path=>{const f=document.createElement('iframe');f.src='/frame';document.body.append(f);f.onload=()=>{f.contentWindow.load(path,false).then(()=>f.dataset.done='true')}},urlpath);await iframeEntered.arrived;await frameResponse;await page.locator('iframe').waitFor();await page.waitForFunction(()=>document.querySelector('iframe')?.dataset.done==='true');const mainEntries=capture.snapshot();assert.equal(mainEntries.filter(x=>x.sha===hash(a)&&x.currentDocument).length,1);outcomes.push({case:'same origin same URL iframe body excluded from main-frame evidence',pass:true});
 const oldepoch=capture.snapshot().find(x=>x.sha===hash(b)).document;await page.reload();assert.equal(capture.find(origin+urlpath,hash(a)),undefined);assert.equal(capture.find(origin+urlpath,hash(b)),undefined);outcomes.push({case:'reload retires all prior same URL completed bodies even same content',pass:true,oldEpoch:oldepoch});
 await complete(b);const reload=await pixels();assert.notEqual(reload.document,oldepoch);outcomes.push({case:'new document actually receives identical immutable body before match',pass:true,reload});
 assert.throws(()=>capture.find(origin+urlpath.replace('/owned/','/other/'),hash(b)),/wrong origin/);assert.equal(capture.find(origin+urlpath.replace('frame=0','frame=1'),hash(b)),undefined);outcomes.push({case:'current owner and source-frame exactness',pass:true});
 const pendingOld=plan(a,true), oldReply=page.waitForResponse(origin+urlpath);await page.evaluate(path=>{window.pending=window.load(path,false).catch(()=>null)},urlpath);await pendingOld.arrived;await oldReply;const oldRequestId=capture.snapshot().at(-1).id;await page.goto(origin+'/newdocument');assert.equal(capture.find(origin+urlpath,hash(a)),undefined);await complete(b);const current=await pixels();pendingOld.response.end(a.subarray(8));assert.equal(capture.find(origin+urlpath,hash(a)),undefined);assert.equal((await pixels()).id,current.id);outcomes.push({case:'200 old document stream crosses navigation; release after current actual B cannot resurrect old epoch',pass:true,oldRequestId,current});
 const other='/api/projects/other/recipes/revisionA/processed?frame=0';plan(a);await page.evaluate(path=>window.load(path,false),other);assert.equal(capture.snapshot().some(x=>x.url===origin+other),false);assert.equal((await pixels()).id,current.id);outcomes.push({case:'actual other-project received body is not current project evidence',pass:true});
 assert.deepEqual(errors,[]);await writeFile(review+'/evidence/response-navigation-boundaries.json',JSON.stringify({source:'dc61fe03f64e644b7ac63057b3f7d7d26df547f8',capturerSourceSHA:hash(Buffer.from(original)),sourceOfBodies:'public original art-water fixtures via controlled actual same-origin HTTP GET200, no server fallback',outcomes,network:events,pageErrors:errors,records:capture.snapshot()},null,2)+'\n');console.log(JSON.stringify({cases:outcomes.length,passed:outcomes.length,pageErrors:errors}));
}finally{capture.dispose();await browser.close();for(const r of holds)r.destroy();server.closeAllConnections();await new Promise(r=>server.close(r))}
